92	func mustRegister(t *testing.T, h http.Handler, id string) {
93		t.Helper()
94		result := doRequest(t, h, http.MethodPost, "/v1/devices", fmt.Sprintf(`{"id":%q}`, id))
95		if result.Code != http.StatusCreated {
96			t.Fatalf("register %s: status = %d body = %s", id, result.Code, result.Body.String())
97		}
98	}
