117	// walkHistory pages through a device's full history, returning all events seen.
118	func walkHistory(t *testing.T, h http.Handler, target string) []historyResponse {
119		t.Helper()
120		var pages []historyResponse
121		cursor := ""
122		for {
123			url := target
124			if cursor != "" {
125				url += "&cursor=" + cursor
126			}
127			result := doRequest(t, h, http.MethodGet, url, "")
128			if result.Code != http.StatusOK {
129				t.Fatalf("history status = %d body = %s", result.Code, result.Body.String())
130			}
131			page := decodeBody[historyResponse](t, result)
132			pages = append(pages, page)
133			if page.NextCursor == nil {
134				return pages
135			}
136			cursor = *page.NextCursor
137		}
138	}
139	
140	func allEvents(t *testing.T, h http.Handler, id string) []Event {
141		t.Helper()
142		pages := walkHistory(t, h, fmt.Sprintf("/v1/devices/%s/history?limit=100", id))
143		var events []Event
144		for _, page := range pages {
145			events = append(events, page.Events...)
146		}
147		return events
148	}
