216			t.Fatalf("new batch must not mark duplicates: %+v", receipt.Samples)
217		}
218	
219		// Events land in array order; the last new sample drives the snapshot.
220		events := allEvents(t, h, "gw")
221		if len(events) != 2 || events[0].Sequence != 1 || events[1].Sequence != 1+1 {
222			t.Fatalf("history = %+v", events)
223		}
224		snapshot := decodeBody[struct {
225			Devices []Device `json:"devices"`
226		}](t, doRequest(t, h, http.MethodGet, "/v1/fleet", ""))
227		if len(snapshot.Devices) != 1 || snapshot.Devices[0].LastTelemetry["b"] != 2 {
228			t.Fatalf("snapshot lastTelemetry = %+v, want b:2 from last new sample", snapshot.Devices)
229		}
230		if !snapshot.Devices[0].LastSeenAt.Equal(*clock) {
231			t.Fatalf("lastSeenAt = %s, want receive time %s", snapshot.Devices[0].LastSeenAt, *clock)
232		}
233	}
