545		if pages[len(pages)-1].NextCursor != nil {
546			t.Fatalf("last page cursor = %v, want null", *pages[len(pages)-1].NextCursor)
547		}
548	
549		// Default limit is 20.
550		first := decodeBody[historyResponse](t, doRequest(t, h, http.MethodGet, "/v1/devices/gw/history", ""))
551		if len(first.Events) != 20 || first.NextCursor == nil {
552			t.Fatalf("default page size = %d cursor=%v, want 20 with cursor", len(first.Events), first.NextCursor)
553		}
554	}
555	
556	func TestHistoryPagingPinsFirstPageHighWater(t *testing.T) {
557		h := NewHandler(NewStore())
558		mustRegister(t, h, "gw")
559		for i := 0; i < 10; i++ {
560			body := replayBody(fmt.Sprintf("b%d", i), sample(fmt.Sprintf("e%d", i), "2024-01-02T10:00:00Z", `{"v":1}`))
561			if r := doRequest(t, h, http.MethodPost, "/v1/devices/gw/replay", body); r.Code != http.StatusAccepted {
562				t.Fatalf("seed status = %d", r.Code)
563			}
564		}
565	
566		first := doRequest(t, h, http.MethodGet, "/v1/devices/gw/history?limit=5", "")
567		page := decodeBody[historyResponse](t, first)
568		if len(page.Events) != 5 || page.NextCursor == nil {
569			t.Fatalf("first page = %+v", page)
570		}
571		cursor := *page.NextCursor
572	
573		// Writes landing between pages must not change the pinned walk.
574		for i := 10; i < 20; i++ {
575			body := replayBody(fmt.Sprintf("b%d", i), sample(fmt.Sprintf("e%d", i), "2024-01-02T10:00:00Z", `{"v":1}`))
576			if r := doRequest(t, h, http.MethodPost, "/v1/devices/gw/replay", body); r.Code != http.StatusAccepted {
577				t.Fatalf("mid-walk insert status = %d", r.Code)
578			}
579		}
580	
581		second := doRequest(t, h, http.MethodGet, "/v1/devices/gw/history?limit=5&cursor="+cursor, "")
582		page2 := decodeBody[historyResponse](t, second)
583		if len(page2.Events) != 5 {
584			t.Fatalf("second page size = %d, want 5", len(page2.Events))
585		}
586		for _, event := range page2.Events {
587			if event.Sequence > 10 {
588				t.Fatalf("paged walk saw sequence %d beyond pinned high-water 10", event.Sequence)
589			}
590		}
591		if page2.NextCursor != nil {
592			t.Fatalf("cursor = %v, want null at pinned end", *page2.NextCursor)
593		}
594	
595		// A fresh first page now sees all 20.
596		fresh := decodeBody[historyResponse](t, doRequest(t, h, http.MethodGet, "/v1/devices/gw/history?limit=100", ""))
597		if len(fresh.Events) != 20 {
598			t.Fatalf("fresh walk events = %d, want 20", len(fresh.Events))
599		}
600	}
601	
602	func TestHistoryCursorValidation(t *testing.T) {
603		h := NewHandler(NewStore())
604		mustRegister(t, h, "a")
605		mustRegister(t, h, "b")
606		body := replayBody("b", sample("e1", "2024-01-02T10:00:00Z", `{"v":1}`))
607		doRequest(t, h, http.MethodPost, "/v1/devices/a/replay", body)
608		doRequest(t, h, http.MethodPost, "/v1/devices/b/replay", body)
609		doRequest(t, h, http.MethodPost, "/v1/devices/a/replay",
610			replayBody("b2", sample("e2", "2024-01-02T11:00:00Z", `{"v":2}`)))
611		doRequest(t, h, http.MethodPost, "/v1/devices/a/replay",
612			replayBody("b3", sample("e3", "2024-01-02T12:00:00Z", `{"v":3}`)))
613	
614		cursor := func(device, query string) string {
615			r := doRequest(t, h, http.MethodGet, "/v1/devices/"+device+"/history?"+query, "")
616			resp := decodeBody[historyResponse](t, r)
617			if resp.NextCursor == nil {
618				t.Fatalf("no cursor for %s?%s", device, query)
619			}
620			return *resp.NextCursor
621		}
622	
623		aCursor := cursor("a", "limit=1")
624	
625		// Foreign device.
626		if r := doRequest(t, h, http.MethodGet, "/v1/devices/b/history?limit=1&cursor="+aCursor, ""); r.Code != http.StatusBadRequest {
627			t.Fatalf("foreign device cursor status = %d, want 400", r.Code)
628		}
629		// Tampered token.
630		tampered := aCursor
631		if tampered[0] == 'A' {
632			tampered = "B" + tampered[1:]
633		} else {
634			tampered = "A" + tampered[1:]
635		}
636		if r := doRequest(t, h, http.MethodGet, "/v1/devices/a/history?limit=1&cursor="+tampered, ""); r.Code != http.StatusBadRequest {
637			t.Fatalf("tampered cursor status = %d, want 400", r.Code)
638		}
639		// Garbage token on a registered device.
640		if r := doRequest(t, h, http.MethodGet, "/v1/devices/a/history?cursor=not-a-cursor", ""); r.Code != http.StatusBadRequest {
641			t.Fatalf("garbage cursor status = %d, want 400", r.Code)
642		}
643		// Cursor reused with a different filter.
644		filteredCursor := cursor("a", "limit=1&from=2024-01-02T10:00:00Z")
645		if r := doRequest(t, h, http.MethodGet, "/v1/devices/a/history?limit=1&from=2024-01-03T00:00:00Z&cursor="+filteredCursor, ""); r.Code != http.StatusBadRequest {
646			t.Fatalf("changed filter cursor status = %d, want 400", r.Code)
647		}
648		// Unknown device is 404, even with a malformed or foreign cursor.
649		if r := doRequest(t, h, http.MethodGet, "/v1/devices/ghost/history?cursor=garbage", ""); r.Code != http.StatusNotFound {
650			t.Fatalf("unknown device cursor status = %d, want 404", r.Code)
651		}
652		if r := doRequest(t, h, http.MethodGet, "/v1/devices/ghost/history?cursor="+aCursor, ""); r.Code != http.StatusNotFound {
653			t.Fatalf("unknown device foreign cursor status = %d, want 404", r.Code)
654		}
655	}
656	
657	func TestHistoryUnknownDevice(t *testing.T) {
658		h := NewHandler(NewStore())
659		if r := doRequest(t, h, http.MethodGet, "/v1/devices/ghost/history", ""); r.Code != http.StatusNotFound {
660			t.Fatalf("status = %d, want 404", r.Code)
661		}
662	}
663	
664	// --- concurrency ------------------------------------------------------------
665	
666	func TestConcurrentReplays(t *testing.T) {
667		h := NewHandler(NewStore())
668		mustRegister(t, h, "gw")
669	
670		const groups = 20
671		const perGroup = 5
672		var start sync.WaitGroup
673		start.Add(1)
674		var wg sync.WaitGroup
675	
676		// Distinct batches, globally unique eventIds.
677		for g := 0; g < groups; g++ {
678			wg.Add(1)
679			go func(g int) {
680				defer wg.Done()
681				start.Wait()
682				samples := make([]string, perGroup)
683				for i := 0; i < perGroup; i++ {
684					samples[i] = sample(fmt.Sprintf("g%d-e%d", g, i), "2024-01-02T10:00:00Z", fmt.Sprintf(`{"g":%d,"i":%d}`, g, i))
685				}
686				r := doRequest(t, h, http.MethodPost, "/v1/devices/gw/replay", replayBody(fmt.Sprintf("batch-g%d", g), samples...))
687				if r.Code != http.StatusAccepted {
688					t.Errorf("group %d status = %d: %s", g, r.Code, r.Body.String())
689				}
690			}(g)
691		}
692	
693		// Same batchId + identical content hammered concurrently: exactly one 202,
694		// the rest 200, never 409.
695		const dupCallers = 8
696		var codesMu sync.Mutex
697		codes := map[int]int{}
698		for c := 0; c < dupCallers; c++ {
699			wg.Add(1)
700			go func() {
701				defer wg.Done()
702				start.Wait()
703				r := doRequest(t, h, http.MethodPost, "/v1/devices/gw/replay",
704					replayBody("dup-batch", sample("dup-event", "2024-01-02T10:00:00Z", `{"v":1}`)))
705				codesMu.Lock()
706				codes[r.Code]++
707				codesMu.Unlock()
708				if r.Code != http.StatusAccepted && r.Code != http.StatusOK {
709					t.Errorf("duplicate batch status = %d: %s", r.Code, r.Body.String())
710				}
711			}()
712		}
713	
714		start.Done()
715		wg.Wait()
716	
717		if codes[http.StatusAccepted] != 1 || codes[http.StatusOK] != dupCallers-1 {
718			t.Fatalf("dup-batch codes = %v, want one 202 and %d 200", codes, dupCallers-1)
719		}
720	
721		events := allEvents(t, h, "gw")
722		want := groups*perGroup + 1
723		if len(events) != want {
724			t.Fatalf("committed events = %d, want %d", len(events), want)
725		}
726		seen := make(map[int64]bool, len(events))
727		for _, event := range events {
728			if seen[event.Sequence] {
729				t.Fatalf("duplicate sequence %d", event.Sequence)
730			}
731			seen[event.Sequence] = true
732		}
733		for seq := int64(1); seq <= int64(want); seq++ {
734			if !seen[seq] {
735				t.Fatalf("sequence %d missing; allocation was not contiguous", seq)
736			}
737		}
738	}
