// --- directory locking --------------------------------------------------------

func TestDataDirectoryLockedToSingleProcess(t *testing.T) {
	dir := filepath.Join(t.TempDir(), "fleet-data")
	first, err := NewPersistentStore(dir)
	if err != nil {
		t.Fatalf("first open: %v", err)
