308	func (s *Store) snapshotLocked() *persistedState {
309		ps := &persistedState{
310			Format:   formatVersion,
311			Instance: s.instance,
312			Devices:  make(map[string]*persistedDevice, len(s.devices)),
313		}
314		for id, state := range s.devices {
315			pd := &persistedDevice{
316				Device:  state.device,
317				Events:  append([]Event(nil), state.events...),
318				ByEvent: make(map[string]int64, len(state.byEvent)),
319				Batches: make(map[string]persistedBatch, len(state.batches)),
320			}
321			pd.Device.LastTelemetry = cloneTelemetry(state.device.LastTelemetry)
322			for i := range pd.Events {
323				pd.Events[i].Values = cloneTelemetry(pd.Events[i].Values)
324			}
325			for eventID, sequence := range state.byEvent {
326				pd.ByEvent[eventID] = sequence
327			}
328			for batchID, batch := range state.batches {
329				samples := append([]Sample(nil), batch.samples...)
330				for i := range samples {
331					samples[i].Values = cloneTelemetry(samples[i].Values)
332				}
333				pd.Batches[batchID] = persistedBatch{Samples: samples, Receipt: cloneReceipt(batch.receipt)}
334			}
335			ps.Devices[id] = pd
336		}
337		return ps
338	}
339	
340	// loadState replaces the in-memory state with recovered state.
341	func (s *Store) loadState(ps *persistedState) {
342		for id, pd := range ps.Devices {
343			state := &deviceState{
344				device:  pd.Device,
345				events:  pd.Events,
346				byEvent: pd.ByEvent,
347				batches: make(map[string]storedBatch, len(pd.Batches)),
348			}
349			for batchID, batch := range pd.Batches {
350				state.batches[batchID] = storedBatch{samples: batch.Samples, receipt: batch.Receipt}
351			}
352			s.devices[id] = state
353		}
354	}
355	
356	// cloneDeviceState deep-copies one device's state for rollback when a
357	// persistence attempt fails.
358	func cloneDeviceState(state *deviceState) *deviceState {
359		clone := &deviceState{
360			device:  state.device,
361			events:  append([]Event(nil), state.events...),
362			byEvent: make(map[string]int64, len(state.byEvent)),
363			batches: make(map[string]storedBatch, len(state.batches)),
364		}
365		clone.device.LastTelemetry = cloneTelemetry(state.device.LastTelemetry)
366		for i := range clone.events {
367			clone.events[i].Values = cloneTelemetry(clone.events[i].Values)
368		}
369		for eventID, sequence := range state.byEvent {
370			clone.byEvent[eventID] = sequence
371		}
372		for batchID, batch := range state.batches {
373			samples := append([]Sample(nil), batch.samples...)
374			for i := range samples {
375				samples[i].Values = cloneTelemetry(samples[i].Values)
376			}
377			clone.batches[batchID] = storedBatch{samples: samples, receipt: cloneReceipt(batch.receipt)}
378		}
379		return clone
380	}
